import http from 'node:http'

export function createApp({ token = process.env.API_TOKEN } = {}) {
  const notes = []
  return http.createServer(async (req, res) => {
    const send = (status, body) => {
      res.writeHead(status, { 'Content-Type': 'application/json' })
      res.end(JSON.stringify(body))
    }
    if (!token || req.headers.authorization !== `Bearer ${token}`) return send(401, { error: 'unauthorized' })
    if (req.url === '/notes' && req.method === 'GET') return send(200, notes)
    if (req.url === '/notes' && req.method === 'POST') {
      let raw = ''
      for await (const chunk of req) raw += chunk
      let data
      try { data = JSON.parse(raw) } catch { return send(400, { error: 'invalid json' }) }
      if (typeof data.title !== 'string' || !data.title.trim()) return send(400, { error: 'title is required' })
      const note = { id: notes.length + 1, title: data.title.trim() }
      notes.push(note)
      return send(201, note)
    }
    return send(404, { error: 'not found' })
  })
}

