import http from 'node:http'

export const RATES_URL = 'https://api.rates.example.com/latest?base=USD'

export function createApp() {
  return http.createServer(async (req, res) => {
    const url = new URL(req.url, 'http://localhost')
    const send = (status, body) => {
      res.writeHead(status, { 'Content-Type': 'application/json' })
      res.end(JSON.stringify(body))
    }
    if (url.pathname !== '/convert') return send(404, { error: 'not found' })
    const amount = Number(url.searchParams.get('amount'))
    const to = url.searchParams.get('to')
    if (!Number.isFinite(amount) || amount <= 0 || !to) return send(400, { error: 'amount and to are required' })
    try {
      const r = await fetch(RATES_URL)
      if (!r.ok) return send(502, { error: 'rates unavailable' })
      const { rates } = await r.json()
      if (!(to in rates)) return send(400, { error: 'unknown currency' })
      return send(200, { amount: Math.round(amount * rates[to] * 100) / 100, currency: to })
    } catch {
      return send(502, { error: 'rates unavailable' })
    }
  })
}
